from pathlib import Path
p=Path('Reference/Linux-0.11-main/kernel/symplus/process.c')
s=p.read_bytes().decode()
s=s.replace('tty_init();printk("SymphonyPlus Linux: interactive boot\\n");', 'tty_init();printk("SymphonyPlus Linux: interactive boot\\n");\r\n    printk("[ OK ] tty_init: 96x40 console ready\\n");\r\n    printk("[ OK ] Memory layout: 8 MiB RAM, 512 KiB user window\\n");')
s=s.replace('occupied[1]=1;ROOT_DEV=0x300;', 'occupied[1]=1;ROOT_DEV=0x300;\r\n    printk("[ OK ] Process scheduler: cooperative, 8 user slots\\n");\r\n    printk("[ OK ] Clock: nanosecond polling enabled\\n");')
s=s.replace('blk_dev_init();symdisk_init();printk("DiskA driver ready\\n");', 'blk_dev_init();printk("[ OK ] blk_dev_init: block request queues ready\\n");\r\n    symdisk_init();printk("[ OK ] DiskA driver ready (8 MiB, big endian)\\n");')
s=s.replace('buffer_init(0x180000);printk("Block cache ready\\n");mount_root();', 'buffer_init(0x180000);printk("[ OK ] buffer_init: block cache ready\\n");\r\n    printk("[    ] Mounting MINIX root filesystem...\\n");mount_root();')
s=s.replace('printk("DiskA MINIX root mounted\\n");', 'printk("[ OK ] MINIX root mounted on DiskA\\n");')
s=s.replace('    sp_resume(ctx);', '    printk("[ OK ] exec: /bin/init loaded as PID 1\\n");\r\n    printk("[ OK ] Kernel initialization complete\\n");\r\n    sp_resume(ctx);')
p.write_bytes(s.encode())
